namespace ghidra.pcode.emu.jit.op;



using ghidra.pcode.emu.jit.analysis;
using ghidra.pcode.emu.jit.var;
using ghidra.pcode.exec.PcodeUseropLibrary;

/**
 * A p-code operator use-def node with two inputs and one output.
 */
public interface JitBinOp : JitDefOp {
	/* @Override */
	string toString(PcodeUseropSymbolMap symbols) {
		return "%s[op=%s, out=%s, l=%s, r=%s]".formatted(
			getClass().getSimpleName(),
			JitOp.toString(op(), symbols),
			@out().toString(symbols.language()),
			l().toString(symbols.language()),
			r().toString(symbols.language()));
	}

	/**
	 * The use-def node for the left input operand
	 * 
	 * @return the input
	 */
	JitVal l();

	/**
	 * The use-def node for the right input operand
	 * 
	 * @return the input
	 */
	JitVal r();

	/* @Override */
	void link() {
		JitDefOp.base.link();
		l().addUse(this, 0);
		r().addUse(this, 1);
	}

	/* @Override */
	void unlink() {
		JitDefOp.base.unlink();
		l().removeUse(this, 0);
		r().removeUse(this, 1);
	}

	/* @Override */
	List<JitVal> inputs() {
		return List.of(l(), r());
	}

	/**
	 * The required type behavior for the left operand
	 * 
	 * @return the behavior
	 */
	JitTypeBehavior lType();

	/**
	 * The required type behavior for the right operand
	 * 
	 * @return the behavior
	 */
	JitTypeBehavior rType();

